cypher.pilot_graph_counts:
MATCH (run:LiteratureRun {run_id:$run_id})
  CALL (run) { MATCH (a:Article)-[:IN_RUN]->(run) RETURN count(a) AS articles }
  CALL (run) { MATCH (n:Concept {run_id:run.run_id}) RETURN count(n) AS concepts }
  CALL (run) { MATCH (e:Evidence {run_id:run.run_id}) RETURN count(e) AS evidence }
  CALL (run) { MATCH (:Concept)-[s:SAME_AS {run_id:run.run_id}]->({backbone_version:'v3'}) RETURN count(s) AS same_as }
  CALL (run) { MATCH (:Concept)-[r {run_id:run.run_id,source:'literature',gate:'AUTO'}]->(:Concept) RETURN count(r) AS auto_concept_relations }
  CALL (run) { MATCH ({backbone_version:'v3'})-[r {run_id:run.run_id,source:'literature',gate:'AUTO'}]->({backbone_version:'v3'}) RETURN count(r) AS auto_backbone_relations }
  RETURN run.run_id AS run_id, articles, concepts, evidence, same_as, auto_concept_relations, auto_backbone_relations
